 "content": "from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = [[False] * w for _ in range(h)]
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or seen[r][c]:
                continue
            q = deque([(r, c)])
            seen[r][c] = True
            comp = []
            colors = set()
            while q:
                y, x = q.popleft()
                comp.append((y, x))
                if grid[y][x] > 1:
                    colors.add(grid[y][x])
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] != 0 and not seen[ny][nx]:
                        seen[ny][nx] = True
                        q.append((ny, nx))
            if colors:
                # Each marked foreground component supplies its color to every
                # foreground cell having a complete 3x3 foreground neighborhood.
                color = min(colors)
                for y, x in comp:
                    if 0 < y < h - 1 and 0 < x < w - 1 and all(
                        grid[yy][xx] != 0
                        for yy in range(y - 1, y + 2)
                        for xx in range(x - 1, x + 2)
                    ):
                        out[y][x] = color
    return out
