   "newText": "from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = [[False] * w for _ in range(h)]
    components = []
    seeds = []
    labels = [[-1] * w for _ in range(h)]
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or seen[r][c]:
                continue
            idx = len(components)
            q = deque([(r, c)])
            seen[r][c] = True
            cells = []
            marks = []
            while q:
                y, x = q.popleft()
                labels[y][x] = idx
                cells.append((y, x))
                if grid[y][x] > 1:
                    marks.append((y, x, grid[y][x]))
                    seeds.append((y, x, grid[y][x], idx))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] != 0 and not seen[ny][nx]:
                        seen[ny][nx] = True
                        q.append((ny, nx))
            components.append(marks)
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            if grid[r][c] != 1 or not all(grid[rr][cc] != 0 for rr in range(r-1, r+2) for cc in range(c-1, c+2)):
                continue
            own = components[labels[r][c]]
            candidates = own if own else seeds
            if candidates:
                _, _, color = min(candidates, key=lambda s: ((r-s[0])**2+(c-s[1])**2, s[2]))
                out[r][c] = color
    return out
